    assert_eq!(value["kind"], "supersede");
    assert_eq!(value["pullRequestNumber"], 42);
    assert_eq!(value["expectedBranch"], "callisto/version-packages");
    assert_eq!(value["replacementBranch"], "callisto/version-packages--sha");
}

