336	fn reason_from_bump(
337	    reason: Option<&BumpReason>,
338	    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
339	) -> Result<ReleaseInclusionReason, GraphError> {
340	    match reason {
341	        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
342	        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
343	        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
344	            group_id: group.to_string(),
345	        }),
346	        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
347	            Ok(ReleaseInclusionReason::FixedGroup {
348	                group_id: group.to_string(),
349	            })
350	        }
351	        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
352	        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
353	            let source = package_ids
354	                .get(via)
355	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
356	                .ok_or(GraphError::ReleaseIntentStale)?;
357	            Ok(ReleaseInclusionReason::Cascade {
358	                from: source,
359	                edge_kind: format!("{dep_kind:?}"),
360	            })
361	        }
362	        Some(BumpReason::PeerEscalation { via, .. }) => {
363	            let source = package_ids
364	                .get(via)
365	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
366	                .ok_or(GraphError::ReleaseIntentStale)?;
367	            Ok(ReleaseInclusionReason::Cascade {
368	                from: source,
369	                edge_kind: "peer".to_string(),
370	            })
371	        }
372	        Some(_) => Err(GraphError::ReleaseIntentStale),
373	    }
374	}
