1	//! Artifact-byte and GitHub-attestation verification for durable releases.
2	//!
3	//! A manifest is only a claim. This module verifies the actual on-disk bytes
4	//! and asks GitHub to validate the signing certificate against the policy
5	//! embedded in the immutable release intent before an executor can upload an
6	//! asset. It intentionally owns no upload side effect.
7	
8	use std::{
9	    fs::{self, File},
10	    path::{Component, Path, PathBuf},
11	    time::Duration,
12	};
13	
14	use callisto_model::{ArtifactManifestV1, CommandRunner, ReleaseIntentV1};
15	
16	use crate::GraphError;
17	
18	const ATTESTATION_TIMEOUT: Duration = Duration::from_secs(120);
19	
20	/// A manifest whose exact local bytes and GitHub provenance have been checked.
21	///
22	/// The constructor is private: callers can obtain this capability only with
23	/// [`verify_artifact_manifest`]. It borrows the manifest so an executor cannot
24	/// silently substitute a different manifest after verification.
25	#[derive(Debug)]
26	pub struct VerifiedArtifactManifest<'a> {
27	    manifest: &'a ArtifactManifestV1,
28	}
29	
30	impl<'a> VerifiedArtifactManifest<'a> {
31	    pub fn manifest(&self) -> &'a ArtifactManifestV1 {
32	        self.manifest
33	    }
34	}
35	
36	/// Verifies every manifest entry against the exact artifact directory.
37	///
38	/// The artifact directory and every candidate are canonicalized, and symbolic
39	/// links are rejected, so a manifest asset name cannot escape the supplied
40	/// build-output directory. Each asset is streamed once for a bounded-memory
41	/// SHA-256 and size comparison. `gh attestation verify` then validates the
42	/// repository, workflow path and commit, source commit, and hosted-runner
43	/// policy declared by the immutable artifact slot.
44	pub fn verify_artifact_manifest<'a, R: CommandRunner>(
45	    intent: &ReleaseIntentV1,
46	    manifest: &'a ArtifactManifestV1,
47	    artifact_root: &Path,
48	    runner: &R,
49	) -> Result<VerifiedArtifactManifest<'a>, GraphError> {
50	    manifest
51	        .validate_for_intent(intent)
52	        .map_err(|source| GraphError::ArtifactManifest { source })?;
53	
54	    let root = canonical_artifact_root(artifact_root)?;
55	    for entry in &manifest.entries {
56	        let path = resolve_asset_path(&root, &entry.slot.asset_name)?;
57	        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
58	            path: path.clone(),
59	            message: error.to_string(),
60	        })?;
61	        let (digest, length) =
62	            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
63	                path: path.clone(),
64	                message: error.to_string(),
65	            })?;
66	        if digest != entry.digest || length != entry.byte_length {
67	            return Err(GraphError::ArtifactBytesMismatch { path });
68	        }
69	
70	        verify_github_attestation(&path, entry, manifest, runner)?;
71	    }
72	    Ok(VerifiedArtifactManifest { manifest })
73	}
