75	fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
76	    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
77	        path: artifact_root.to_path_buf(),
78	        message: error.to_string(),
79	    })?;
80	    if !metadata.is_dir() {
81	        return Err(GraphError::UnsafeArtifactPath {
82	            path: artifact_root.to_path_buf(),
83	            reason: "artifact root is not a directory",
84	        });
85	    }
86	    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
87	        path: artifact_root.to_path_buf(),
88	        message: error.to_string(),
89	    })
90	}
