130	fn verify_github_attestation<R: CommandRunner>(
131	    path: &Path,
132	    entry: &callisto_model::ArtifactManifestEntryV1,
133	    manifest: &ArtifactManifestV1,
134	    runner: &R,
135	) -> Result<(), GraphError> {
136	    let policy = &entry.slot.attestation_policy;
137	    let workflow = format!("{}/{}", policy.repository, policy.workflow_path);
138	    let path_argument = path.to_string_lossy();
139	    let source_commit = manifest.source_commit.as_str();
140	    let args = [
141	        "attestation",
142	        "verify",
143	        path_argument.as_ref(),
144	        "--repo",
145	        policy.repository.as_str(),
146	        "--signer-workflow",
147	        workflow.as_str(),
148	        "--signer-digest",
149	        policy.workflow_commit.as_str(),
150	        "--source-digest",
151	        source_commit,
152	        "--deny-self-hosted-runners",
153	    ];
154	    let output = runner
155	        .run_with_timeout(
156	            "gh",
157	            &args,
158	            path.parent().unwrap_or_else(|| Path::new(".")),
159	            ATTESTATION_TIMEOUT,
160	        )
161	        .map_err(|error| GraphError::ArtifactAttestation {
162	            path: path.to_path_buf(),
163	            message: error.to_string(),
164	        })?;
165	    if output.success() {
166	        Ok(())
167	    } else {
168	        Err(GraphError::ArtifactAttestation {
169	            path: path.to_path_buf(),
170	            message: "GitHub attestation verification failed".to_owned(),
171	        })
172	    }
173	}
