const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          category: { type: 'string', enum: ['duplicate-logic', 'over-engineering'] },
          title: { type: 'string' },
          primary_file: { type: 'string' },
          primary_lines: { type: 'string' },
          description: { type: 'string' },
          other_locations: {
            type: 'array',
            items: {
              type: 'object',
              properties: { file: { type: 'string' }, lines: { type: 'string' } },
              required: ['file'],
            },
          },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
        },
        required: ['category', 'title', 'primary_file', 'description', 'severity'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: { confirmed: { type: 'boolean' }, rationale: { type: 'string' } },
  required: ['confirmed', 'rationale'],
}

function scanPrompt(area) {
  return `You are auditing a Rust workspace (Callisto, a monorepo release/versioning tool) for exactly two anti-patterns -- nothing else.

1. duplicate-logic: the same domain concept or algorithm implemented independently in two or more places, at risk of drifting apart. Real example already found and fixed in this repo: a function re-implemented changeset-to-package resolution that a different function already computed correctly, and the two silently disagreed -- breaking every release in a fixed-group workspace.
2. over-engineering: unnecessary abstraction, indirection, generality, or config plumbing for what the problem actually requires -- an interface/trait with exactly one real implementation and no second one planned, a generic mechanism solving a problem that only ever has one concrete shape, a config knob nothing reads, a layer that only forwards to the layer below it.

Your primary files (read every one, in full):
${area.files.map((f) => `- ${f}`).join('\n')}

You have full repository read access (Read/Grep/Glob across the whole workspace, not just these files). For anything in your primary files that looks like it might also exist elsewhere -- a parsing routine, a shell-command wrapper, a validation rule, a resolution algorithm -- grep the rest of crates/*/src for the same concept and report the other location(s) if you find them. Cross-crate duplication is exactly the highest-value finding here.

Out of scope, do NOT report: correctness bugs, security issues, missing tests, style/formatting nits, or anything that isn't squarely about duplication or over-engineering. Another audit already covers correctness separately.

For each finding: category, a short title, primary_file, primary_lines (e.g. "120-145"), a description explaining WHY it's duplication or over-engineering (not a description of what the code does), other_locations if it's duplicate-logic, and severity (high = real behavioral-drift risk or major maintenance burden, medium = worth fixing but contained, low = minor/stylistic). Only report things you're at least moderately confident about -- do not pad the list to seem thorough. It's fine to return zero findings if this area is genuinely clean.`
}

function verifyPrompt(finding) {
  return `Adversarially verify one finding from a codebase audit of the Callisto Rust workspace. Default to confirmed=false unless you personally read the code and can confirm it.

Finding:
${JSON.stringify(finding, null, 2)}

Read primary_file (and every file in other_locations) directly, at the referenced lines and their surrounding context.
- For duplicate-logic: confirm the locations really implement the same domain concept, not just superficially similar syntax. Two functions that both loop over a Vec are not "duplicate logic"; two functions that both compute the same release-authorization decision are.
- For over-engineering: confirm the abstraction is genuinely unused/unnecessary. A single implementation today does not automatically mean over-engineering -- check for a second call site, a documented extension point, or a test-only seam that justifies it before declaring it over-engineered.

Return confirmed (true only if independently verified against the real code) and a one-to-three-sentence rationale.`
}

phase('Scan')
const scanned = await parallel(
  AREAS.map((area) => () => agent(scanPrompt(area), { phase: 'Scan', label: area.name, effort: 'high', schema: FINDINGS_SCHEMA }))
)
const rawFindings = scanned
  .filter(Boolean)
  .flatMap((r, i) => r.findings.map((f) => ({ ...f, source_area: AREAS[i].name })))
log(`Scan complete: ${rawFindings.length} raw findings across ${AREAS.length} areas`)

phase('Merge')
let deduped = rawFindings
if (rawFindings.length > 0) {
  const merged = await agent(
    `You have ${rawFindings.length} raw findings from independent auditors, each scoped to a different part of a Rust workspace, hunting for (1) duplicate-logic and (2) over-engineering. Multiple auditors may have surfaced the SAME underlying issue from different sides -- e.g. the auditor covering file X reports "X duplicates Y", and the auditor covering file Y independently reports the same pair the other way around.\n\nMerge near-duplicate findings into one (keep the clearer title/description, union the other_locations). Do NOT merge findings that are merely similar in category but describe genuinely different code -- when in doubt, keep them separate.\n\nRaw findings:\n${JSON.stringify(rawFindings, null, 2)}\n\nReturn the deduplicated findings array in the exact same shape.`,
    { phase: 'Merge', model: 'opus', effort: 'high', schema: FINDINGS_SCHEMA }
  )
  if (merged && Array.isArray(merged.findings)) deduped = merged.findings
  log(`Merge complete: ${rawFindings.length} raw -> ${deduped.length} deduplicated findings`)
}

phase('Verify')
const verdicts = await parallel(
  deduped.map((f) => () => agent(verifyPrompt(f), { phase: 'Verify', label: f.title, effort: 'high', schema: VERDICT_SCHEMA }))
)
const confirmed = deduped
  .map((f, i) => ({ finding: f, verdict: verdicts[i] }))
  .filter((x) => x.verdict && x.verdict.confirmed)
  .map((x) => ({ ...x.finding, verification_rationale: x.verdict.rationale }))
log(`Verify complete: ${confirmed.length}/${deduped.length} findings survived adversarial verification`)

phase('Synthesize')
let synthesis = 'No findings survived verification -- nothing to synthesize.'
if (confirmed.length > 0) {
  synthesis = await agent(
    `You are given ${confirmed.length} verified, adversarially-confirmed findings from a deep audit of the Callisto Rust workspace, covering two specific anti-pattern categories: duplicate/parallel implementations of the same domain logic, and unnecessary complexity/over-engineering.\n\nConfirmed findings:\n${JSON.stringify(confirmed, null, 2)}\n\nContext: this audit was requested immediately after discovering and fixing a real production bug of exactly the duplicate-logic kind -- a function in the release pipeline re-implemented changeset/group/cascade resolution logic that another function already computed correctly, and the two disagreed, breaking every release in a fixed-group workspace. The fix replaced re-derivation with trusting a single persisted, digest-verified decision.\n\nIf helpful, read .claude/semantic-model/*.md and .claude/specs/*.json in the repository for architectural context and existing invariants -- you have full repo access.\n\nProduce a report with:\n1. Findings grouped into architectural PATTERNS, not a flat list -- what recurring root cause produces multiple instances (e.g. "no single source of truth for X", "a seam designed for extensibility that never got a second implementation", "the same shell-command wrapping duplicated across N crates")?\n2. For each pattern, a whole-system structural fix proposal -- something that makes the pattern impossible to recur, not a patch to each instance one at a time.\n3. A priority ranking across patterns, weighing: number of instances, whether it sits on the release/publish critical path (this repo's own history shows that path is where duplication has caused real production incidents), and fix cost vs. risk of leaving it.\n4. A short list of anything borderline/low-confidence you'd flag for human triage rather than act on directly.\n\nWrite it as a clear, well-organized markdown report a senior engineer could act on directly -- headers, not a wall of prose.`,
    { phase: 'Synthesize', model: 'opus', effort: 'xhigh' }
  )
}

return { raw_finding_count: rawFindings.length, deduped_count: deduped.length, confirmed, synthesis }

