70	    pub(crate) fn validate_syntactic(raw: &RawGroupTable) -> Result<(), ConfigError> {
71	        let mut seen_names = BTreeSet::new();
72	
73	        for g in &raw.fixed {
74	            if !seen_names.insert(&g.name) {
75	                return Err(ConfigError::DuplicateGroupName { group: g.name.clone() });
76	            }
77	            if g.members.is_empty() {
78	                return Err(ConfigError::EmptyGroup { group: g.name.clone() });
79	            }
80	        }
81	
82	        for g in &raw.linked {
83	            if !seen_names.insert(&g.name) {
84	                return Err(ConfigError::DuplicateGroupName { group: g.name.clone() });
85	            }
86	            if g.members.is_empty() {
87	                return Err(ConfigError::EmptyGroup { group: g.name.clone() });
88	            }
89	        }
90	
91	        let mut fixed_members = BTreeMap::new();
92	        for g in &raw.fixed {
93	            for m in &g.members {
94	                if let Some(other) = fixed_members.insert(m.as_str(), &g.name) {
95	                    return Err(ConfigError::ConflictingGroupNames {
96	                        group: g.name.clone(),
97	                        other: (*other).clone(),
98	                        member: m.clone(),
99	                    });
100	                }
101	            }
102	        }
103	
104	        let mut linked_members = BTreeMap::new();
105	        for g in &raw.linked {
106	            for m in &g.members {
107	                if let Some(other) = linked_members.insert(m.as_str(), &g.name) {
108	                    return Err(ConfigError::ConflictingGroupNames {
109	                        group: g.name.clone(),
110	                        other: (*other).clone(),
111	                        member: m.clone(),
112	                    });
113	                }
114	                if let Some(other_fixed) = fixed_members.get(m.as_str()) {
115	                    return Err(ConfigError::ConflictingGroupNames {
116	                        group: g.name.clone(),
117	                        other: (*other_fixed).clone(),
118	                        member: m.clone(),
119	                    });
120	                }
121	            }
122	        }
123	
124	        Ok(())
