127	    pub(crate) fn resolve(raw: &RawGroupTable, index: &IdentityIndex) -> Result<GroupTable, GraphError> {
128	        let mut fixed = BTreeMap::new();
129	        let mut linked = BTreeMap::new();
130	        let mut fixed_of = BTreeMap::new();
131	        let mut linked_of = BTreeMap::new();
132	        let mut claimed_by: BTreeMap<PackageId, GroupName> = BTreeMap::new();
133	
134	        for rg in &raw.fixed {
135	            let mut members = Vec::new();
136	            for name in &rg.members {
137	                if let Ok(id) = index.resolve_human(name, &[]) {
138	                    if let Some(other) = claimed_by.get(&id) {
139	                        if other != &rg.name {
