423	    let versioning: &dyn callisto_format::Versioning = match base.grammar() {
424	        callisto_model::VersionGrammar::Pep440 => &callisto_format::Pep440Versioning,
425	        _ => &callisto_format::SemVerVersioning,
426	    };
427	
428	    if let Some(pre) = input.pre {
429	        if pre.mode == callisto_format::PreMode::Pre {
430	            let pinned_base = pre.initial_versions.get(id.name()).unwrap_or(&base);
