function verifyPrompt(finding) {
  return `Adversarially verify one finding from a second-pass audit of the Callisto Rust workspace (rooted at ${ROOT}). Default to confirmed=false unless you personally read the code and can confirm it.

Finding:
${JSON.stringify(finding, null, 2)}

