//! End-to-end coverage for the ConfigProvenance rendering fix: before it,
//! `render_version`'s text output never consulted `BumpRecord.governed_by`,
//! so an operator running the real CLI had no way to see which
//! `callisto.toml` key (or default) drove a cascade bump. The in-process
//! unit test next to the fix (`render/mod.rs`) proves `render_version`
//! itself is wired correctly against a hand-built `VersionReport`; this
//! test proves the attribution line survives all the way from a real
//! dependency graph, through the cascade solver, to the actual text a user
//! sees on stdout.

use std::path::Path;
use std::process::Command;

fn callisto_bin() -> &'static str {
    env!("CARGO_BIN_EXE_callisto")
}

fn git_init(root: &Path) {
    for args in [
        vec!["init", "-q", "-b", "main"],
        vec!["config", "user.name", "Callisto Tester"],
        vec!["config", "user.email", "tester@callisto.dev"],
        vec!["config", "commit.gpgsign", "false"],
        vec!["config", "tag.gpgsign", "false"],
    ] {
        assert!(Command::new("git")
            .args(&args)
            .current_dir(root)
            .status()
            .unwrap()
            .success());
    }
}

fn git_commit_all(root: &Path, message: &str) {
    assert!(Command::new("git")
        .args(["add", "-A"])
        .current_dir(root)
        .status()
        .unwrap()
        .success());
    assert!(Command::new("git")
        .args(["commit", "-q", "-m", message])
        .current_dir(root)
        .status()
        .unwrap()
        .success());
}

fn run_callisto_text(root: &Path, args: &[&str]) -> String {
    let output = Command::new(callisto_bin())
        .arg("--cwd")
        .arg(root)
        .args(args)
        .output()
        .expect("failed to spawn callisto binary");
    assert!(
        output.status.success(),
        "callisto {args:?} failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).into_owned()
}

/// A cascade-driven bump (upstream-crate goes major, downstream-crate's
/// `"1.0"` requirement no longer covers it) must print a "governed by
/// [cascade].bump-severity" attribution line beneath the bump in the real
/// text renderer a user sees -- not just in a hand-constructed
/// `VersionReport` fed directly to `render_version` in a unit test.
#[test]
fn version_dry_run_text_output_shows_cascade_attribution_for_a_real_dependency_graph() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    git_init(root);

    std::fs::write(
        root.join("Cargo.toml"),
        "[workspace]\nmembers = [\"crates/upstream-crate\", \"crates/downstream-crate\"]\nresolver = \"2\"\n",
    )
    .unwrap();
    std::fs::write(root.join("callisto.toml"), "").unwrap();

    std::fs::create_dir_all(root.join("crates/upstream-crate/src")).unwrap();
    std::fs::write(
        root.join("crates/upstream-crate/Cargo.toml"),
        "[package]\nname = \"upstream-crate\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
    std::fs::write(root.join("crates/upstream-crate/src/lib.rs"), "pub fn hello() {}\n").unwrap();

    std::fs::create_dir_all(root.join("crates/downstream-crate/src")).unwrap();
    std::fs::write(
        root.join("crates/downstream-crate/Cargo.toml"),
        "[package]\nname = \"downstream-crate\"\nversion = \"1.0.0\"\nedition = \"2021\"\n\n[dependencies]\nupstream-crate = { path = \"../upstream-crate\", version = \"1.0\" }\n",
    )
    .unwrap();
    std::fs::write(root.join("crates/downstream-crate/src/lib.rs"), "pub fn world() {}\n").unwrap();

    git_commit_all(root, "Initial commit");

    let add_out = run_callisto_text(
        root,
        &["add", "--package", "upstream-crate:major", "--summary", "breaking change"],
    );
    assert!(add_out.contains("Added changeset"), "add did not succeed: {add_out}");

    let plan_text = run_callisto_text(root, &["version", "--dry-run"]);

    assert!(
        plan_text.contains("upstream-crate 1.0.0"),
        "upstream-crate's own bump must be listed: {plan_text}"
    );
    assert!(
        plan_text.contains("downstream-crate"),
        "downstream-crate must cascade since its \"1.0\" requirement no longer covers 2.0.0: {plan_text}"
    );
    assert!(
        plan_text.contains("governed by [cascade].bump-severity"),
        "the cascade-driven bump must print its ConfigProvenance attribution line in real CLI text output: {plan_text}"
    );
}

//! End-to-end coverage for the severity-validation message fix: before it,
//! `callisto add --package name:severity` claimed the allowed values were
//! "patch, minor, or major", omitting `none` even though `Severity` has
//! always accepted it. The unit tests next to the fix (`add.rs`) call
//! `parse_severity` directly; these prove the corrected wording -- and the
//! previously-undocumented `none` acceptance -- reach the real CLI's actual
//! stderr/stdout, exactly what an operator sees when they mistype a
//! severity.
//!
//! The lock-contention and identity-resolution fixes in the same PR are not
//! covered here: both are already exercised against a *real* OS-level
//! primitive (a real `fs2` file lock; a real malformed-manifest parse) in
//! their unit tests, and neither has a simple, direct CLI trigger --
//! `IdentityResolver::resolve`'s error paths are graph-internal, and
//! reproducing real lock contention at the CLI level requires a second
//! concurrent process. Noting the gap explicitly rather than skipping it in
//! silence, per this repo's sibling-gap discipline.

use std::path::Path;
use std::process::Command;

fn callisto_bin() -> &'static str {
    env!("CARGO_BIN_EXE_callisto")
}

fn setup_minimal_workspace() -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();

    for args in [
        vec!["init", "-q", "-b", "main"],
        vec!["config", "user.name", "Callisto Tester"],
        vec!["config", "user.email", "tester@callisto.dev"],
        vec!["config", "commit.gpgsign", "false"],
        vec!["config", "tag.gpgsign", "false"],
    ] {
        assert!(Command::new("git")
            .args(&args)
            .current_dir(root)
            .status()
            .unwrap()
            .success());
    }

    std::fs::write(
        root.join("Cargo.toml"),
        "[workspace]\nmembers = [\"crates/demo\"]\nresolver = \"2\"\n",
    )
    .unwrap();
    std::fs::create_dir_all(root.join("crates/demo/src")).unwrap();
    std::fs::write(
        root.join("crates/demo/Cargo.toml"),
        "[package]\nname = \"demo\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
    std::fs::write(root.join("crates/demo/src/lib.rs"), "pub fn hello() {}\n").unwrap();
    std::fs::write(root.join("callisto.toml"), "").unwrap();

    assert!(Command::new("git")
        .args(["add", "-A"])
        .current_dir(root)
        .status()
        .unwrap()
        .success());
    assert!(Command::new("git")
        .args(["commit", "-q", "-m", "Initial commit"])
        .current_dir(root)
        .status()
        .unwrap()
        .success());

    dir
}

fn run_add(root: &Path, package_spec: &str) -> std::process::Output {
    Command::new(callisto_bin())
        .arg("--cwd")
        .arg(root)
        .args(["add", "--package", package_spec, "--summary", "test"])
        .output()
        .expect("failed to spawn callisto binary")
}

/// Error case: an invalid severity must be rejected, and the corrected
/// message must list every value `Severity` actually accepts -- including
/// `none`, which the pre-fix message omitted.
#[test]
fn add_rejects_invalid_severity_with_the_full_accepted_value_list() {
    let dir = setup_minimal_workspace();
    let output = run_add(dir.path(), "demo:bogus");

    assert!(!output.status.success(), "an invalid severity must fail");
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        stderr.contains("Must be none, patch, minor, or major"),
        "stderr must list all four accepted severities, including `none`: {stderr}"
    );
}

/// Happy/corner-case path: `none` has always been a valid severity value at
/// the parser level; this proves it still round-trips end to end through
/// the real CLI (not just through the previously-inaccurate error message).
#[test]
fn add_accepts_none_severity() {
    let dir = setup_minimal_workspace();
    let output = run_add(dir.path(), "demo:none");

    assert!(
        output.status.success(),
        "`none` must be accepted as a valid severity: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("Added changeset"), "expected a changeset to be written: {stdout}");
}

/// The three ordinary severities must keep working unchanged (regression
/// guard around the corrected message/parse path).
#[test]
fn add_accepts_patch_minor_major() {
    let dir = setup_minimal_workspace();
    for severity in ["patch", "minor", "major"] {
        let output = run_add(dir.path(), &format!("demo:{severity}"));
        assert!(
            output.status.success(),
            "`{severity}` must still be accepted: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }
}

