222	/// Builds a release intent from a fresh root-bound observation.
223	pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
224	    root: &Path,
225	    locator: &L,
226	    runner: &R,
227	    decision: &ReleaseDecisionV1,
228	    trust_profile: ExecutionTrustProfileV1,
229	) -> Result<ReleaseIntentV1, GraphError> {
230	    let root = canonical_root(root)?;
231	    let workspace = Workspace::load(root.clone(), locator, runner)?;
232	    let source = observe_source(&workspace, trust_profile)?;
233	    let intent = derive_release_intent(&workspace, decision, source.clone(), trust_profile)?;
234	
235	    // Recheck after all input reads. A concurrent edit or checkout cannot be
236	    // authorized merely because it happened after the first check.
237	    if observe_source(&workspace, trust_profile)? != source {
238	        return Err(GraphError::ReleaseIntentStale {
239	            reason: StaleReason::source_identity_changed(),
240	        });
241	    }
242	    Ok(intent)
243	}
