267	    let after_versions = resolve_batch_versions(after_blobs, &manifest_queries)?;
268	
269	    let mut observed = std::collections::BTreeSet::new();
270	    let mut manifest_index = 0usize;
271	    for package in workspace.graph.packages() {
272	        let package_ids = release_package_ids(package)?;
273	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
274	        if package_is_claimed {
275	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
276	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
277	            })?;
278	            if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
