285	        for (manifest, id) in package.canonical_manifests().zip(package_ids) {
286	            let path = manifest.path.to_string_lossy();
287	            let before = &before_versions[manifest_index];
288	            let after = &after_versions[manifest_index];
289	            manifest_index += 1;
290	            let changed_version = before != after;
291	            match claimed.get(&id) {
292	                Some(target_version) => {
293	                    if !changed_paths.contains(path.as_ref()) {
294	                        return Err(GraphError::ReleaseCommitVerificationFailed {
