306	                }
307	                None => {
308	                    if changed_version {
309	                        // A changed version the committed decision never
310	                        // claimed is not this commit's authority -- fail
311	                        // closed rather than trust a partial match.
312	                        return Err(GraphError::ReleaseCommitVerificationFailed {
313	                            commit: release_commit.clone(),
314	                            reason: CommitVerificationFailure::UnclaimedVersionChange,
315	                        });
316	                    }
317	                }
318	            }
319	        }
320	    }
321	    if observed.len() != claimed.len() {
322	        return Err(GraphError::ReleaseCommitVerificationFailed {
323	            commit: release_commit.clone(),
324	            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
325	        });
326	    }
327	
328	    Ok(decision)
