359	    fn assert_release_reason_has_content(body: &str) {
360	        let start = body
361	            .find("#### Release Reason")
362	            .expect("must contain '#### Release Reason'");
363	        let after_heading = &body[start + "#### Release Reason".len()..];
364	        let end = after_heading.find("</details>").unwrap_or(after_heading.len());
365	        let section = after_heading[..end].trim();
