5	pub fn render_section(input: &ChangelogInput) -> Result<String, ChangelogError> {
6	    if input.entries.is_empty() {
7	        return Err(ChangelogError::EmptyInput);
8	    }
9	    for entry in &input.entries {
10	        if entry.severity == callisto_model::Severity::None {
11	            return Err(ChangelogError::SeverityNoneEntry);
12	        }
13	    }
14	
15	    let mut out = String::new();
16	
17	    let heading = match &input.to {
18	        Some(v) => format!("## {}", v.render()),
19	        None => "## Unreleased".to_string(),
20	    };
21	    out.push_str(&heading);
22	    out.push('\n');
23	    out.push('\n');
24	
25	    let mut dep_updates = Vec::new();
26	
27	    for entry in &input.entries {
28	        match &entry.source {
29	            ChangeSource::Changeset { summary, .. } => {
30	                if summary.trim().is_empty() {
31	                    continue;
32	                }
33	                let indented = summary.trim_end_matches('\n');
34	                let indented = indented.replace('\n', "\n  ");
35	                out.push_str(&format!("- {indented}\n"));
36	            }
37	            ChangeSource::Commit { subject, sha } => {
38	                out.push_str(&format!("- {subject} ({})\n", sha.short()));
39	            }
40	            ChangeSource::DependencyUpdate { dependency, to, .. } => {
41	                dep_updates.push((dependency, to));
42	            }
43	            ChangeSource::PeerEscalation { dependency, to } => {
44	                out.push_str(&format!(
45	                    "- Peer dependency `{}` requires `{}`\n",
46	                    dependency.display_name(),
47	                    to.render()
48	                ));
49	            }
50	            ChangeSource::GroupUnion { group, kind } => {
51	                let k_str = match kind {
52	                    GroupKind::Fixed => "fixed",
53	                    GroupKind::Linked => "linked",
54	                };
55	                out.push_str(&format!("- Released together with the `{group}` {k_str} group.\n"));
56	            }
57	            ChangeSource::NewGroupMember { group } => {
58	                out.push_str(&format!("- Joined the `{group}` group at this version.\n"));
59	            }
60	        }
61	    }
62	
63	    if !dep_updates.is_empty() {
64	        out.push_str("- Dependency updates\n");
65	        for (dep, to_ver) in dep_updates {
66	            out.push_str(&format!("  - `{}` → `{}`\n", dep.display_name(), to_ver.render()));
67	        }
68	    }
69	
70	    Ok(out)
71	}
